import sys
from collections import OrderedDict

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        print("")
        return

    n = int(data[0].strip())
    shopping_list = OrderedDict()

    for i in range(1, n + 1):
        if i >= len(data):
            break
        line = data[i].strip()
        if not line:
            continue

        parts = line.split(" ", 1)
        if len(parts) < 2:
            continue

        operation = parts[0].upper()
        item = parts[1]

        if operation == "ADD":
            if item in shopping_list:
                del shopping_list[item]
            shopping_list[item] = True
        elif operation == "REMOVE":
            if item in shopping_list:
                del shopping_list[item]

    items = list(shopping_list.keys())
    if items:
        print(", ".join(items))
    else:
        print("")

if __name__ == "__main__":
    main()
